<?php declare(strict_types=1); namespace Core\Console\Commands; use Core\Console\Command; use Core\Database\DatabaseManager; use Core\Database\Migration\Migrator; use Core\Database\Schema\SchemaBuilder; final class RollbackCommand extends Command { protected string $name = 'rollback'; protected string $description = 'Roll back the last migration batch (use --steps=N for more).'; public function handle(array $args, array $options): int { $connection = $this->app->get(DatabaseManager::class)->connection(); $migrator = new Migrator( $connection, new SchemaBuilder($connection), $this->app->basePath('database/migrations'), ); $steps = (int) $this->option($options, 'steps', '1'); $rolledBack = $migrator->rollback($steps); if ($rolledBack === []) { $this->line('Nothing to roll back.'); return 0; } foreach ($rolledBack as $migration) { $this->info('Rolled back: ' . $migration); } return 0; } } 